                if line[i] == '"':
                    # Check for doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check that next char is comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        if i < len(line):
                            i += 1  # skip comma
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
            fields.append(field)
